head.script:
scwin.onpageload = function() {
    //dc_schedule.setJSON( holidayObj );
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 개발자도구(F12)를 이용해서 head영역의 link herf 속성순서를 확인한다.
    //1. After running the sample, use the developer tool (F12) to check the link herf attribute order in the head area.
    //Verify step 1. stylesheet_ext.css -> fullcalendar.css -> scheduleCalendar_CSS_WEFF-180_ (WSQ-3272) .css.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('head').find('link')[0].href.indexOf('stylesheet_ext.css') != -1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('head').find('link')[1].href.indexOf('fullcalendar.css') != -1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('head').find('link')[2].href.indexOf('scheduleCalendar_CSS_WEFF-180_(WSQ-3272).css') != -1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    window.log = WebSquare.wUnit.getJq('head').find('link')[0].href
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
